# Hypothesis: a @final class rejects subclassing and a Final dataclass field rejects reassignment for checkers, while CPython only raises on the guarded frozen write.
from dataclasses import dataclass
from typing import ClassVar, Final, final, reveal_type


@final
class Config:
    LIMIT: Final[int] = 3
    registry: ClassVar[list[str]] = []

    def __init__(self, label: str) -> None:
        self.label: Final = label
        Config.registry.append(label)


class Sub(Config):  # expect-error
    pass


@dataclass(frozen=True)
class Point:
    x: Final[int]
    y: int


def try_reassign(p: Point) -> str:
    try:
        p.x = 5  # expect-error
    except AttributeError:
        return 'frozen'
    return 'mutable'


def describe(c: Config) -> str:
    reveal_type(c.registry)
    reveal_type(Config.LIMIT)
    return c.label + str(Config.LIMIT)


s = Sub('sub')
print(describe(Config('base')), describe(s))
print(try_reassign(Point(1, 2)))
print(Point(1, 2), Config.registry)
